import { fileURLToPath } from 'node:url';

// Resolved from this file so they work from src/ (tsx), dist/ (node) and inside Docker,
// where the repo root is "/" (apps/api is deployed to /app, data to /data).

/** SQL migrations generated by drizzle-kit (apps/api/drizzle). */
export const MIGRATIONS_DIR = fileURLToPath(new URL('../../drizzle', import.meta.url));

/** Case studies seeded into portfolio_cases (data/portfolio at the repo root). */
export const DEFAULT_PORTFOLIO_DIR = fileURLToPath(
  new URL('../../../../data/portfolio', import.meta.url),
);
